#' Augmented Synthetic Control
#'
#' 
#' @param data .
#' @param outcome .
#' @param unit .
#' @param time .
#' @param predictors Auxiliary covariates, averaged over the pre-treatment
#'   periods (missing values omitted), as in the augsynth package.
#' @param treatedUnit .
#' @param extraTreated Further units treated in the same first period; their
#'   outcomes are averaged with the treated unit.
#' @param treatmentTime .
#' @param donorExclude .
#' @param progfunc .
#' @param scm .
#' @param fixedeff .
#' @param residualize .
#' @param lambdaText .
#' @param min1se .
#' @param infType .
#' @param alpha .
#' @param conformalType .
#' @param nPerm .
#' @param gridSize .
#' @param seed .
#' @param showPath .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$balance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$gapsPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
ascm <- function(
    data,
    outcome,
    unit,
    time,
    predictors,
    treatedUnit,
    extraTreated = "",
    treatmentTime = 2000,
    donorExclude = "",
    progfunc = "ridge",
    scm = TRUE,
    fixedeff = FALSE,
    residualize = FALSE,
    lambdaText = "",
    min1se = TRUE,
    infType = "conformal",
    alpha = 0.05,
    conformalType = "iid",
    nPerm = 1000,
    gridSize = 50,
    seed = 1,
    showPath = FALSE,
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ascm requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(unit), unit, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(predictors), predictors, NULL))


    options <- ascmOptions$new(
        outcome = outcome,
        unit = unit,
        time = time,
        predictors = predictors,
        treatedUnit = treatedUnit,
        extraTreated = extraTreated,
        treatmentTime = treatmentTime,
        donorExclude = donorExclude,
        progfunc = progfunc,
        scm = scm,
        fixedeff = fixedeff,
        residualize = residualize,
        lambdaText = lambdaText,
        min1se = min1se,
        infType = infType,
        alpha = alpha,
        conformalType = conformalType,
        nPerm = nPerm,
        gridSize = gridSize,
        seed = seed,
        showPath = showPath,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- ascmClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

